local GlassRibbonMaker = {}
local PRODUCTS = {
    iron_glass_ribbon = { name = "Železni trak za steklo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 165, prestige = 4, happiness = 2, description = "Železni trak za okrasno steklo." },
    bronze_glass_ribbon = { name = "Bronast trak za steklo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 400, prestige = 6, happiness = 3, description = "Bronast trak za okrasno steklo." },
    silver_glass_ribbon = { name = "Srebrni trak za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 970, prestige = 11, happiness = 4, description = "Srebrni trak za plemiško steklo." },
    gilded_glass_ribbon = { name = "Pozlačeni trak za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2100, prestige = 20, happiness = 5, description = "Pozlačeni trak za dvorno steklo." },
    jewel_set_glass_ribbon = { name = "Draguljasti trak za steklo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4550, prestige = 36, happiness = 7, description = "Draguljasti trak za kraljevsko steklo." },
    royal_sovereign_glass_ribbon = { name = "Kraljevski suvereni trak za steklo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 9800, prestige = 68, happiness = 13, description = "Suvereni trak z biseri za krono." },
}
local BUILDINGS = {
    glassribbon_workshop = { name = "Trakovna delavnica", cost = { gold = 340, wood = 180, stone = 130, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    glassribbon_house = { name = "Trakovna hiša", cost = { gold = 1210, wood = 365, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassribbon_atelier = { name = "Mojstrski trakovni atelje", cost = { gold = 3030, wood = 420, stone = 520, silver = 36, gold = 7 }, upkeep = 71, qualityBonus = 30 },
    sovereign_glassribbon_palace = { name = "Suverena trakovna palača", cost = { gold = 13050, wood = 650, stone = 830, gold = 84, jewel = 19 }, upkeep = 255, qualityBonus = 55, prestigeBonus = 50 },
}
GlassRibbonMaker.ironStock = 14; GlassRibbonMaker.bronzeStock = 12; GlassRibbonMaker.woodStock = 12; GlassRibbonMaker.leatherStock = 10; GlassRibbonMaker.silverStock = 8; GlassRibbonMaker.goldStock = 6; GlassRibbonMaker.jewelStock = 4; GlassRibbonMaker.pearlStock = 4
GlassRibbonMaker.productStock = {}; GlassRibbonMaker.buildings = {}; GlassRibbonMaker.maker = nil; GlassRibbonMaker.activeMaking = {}; GlassRibbonMaker.totalProducts = 0; GlassRibbonMaker.dayTimer = 0
function GlassRibbonMaker.init() GlassRibbonMaker.ironStock=14; GlassRibbonMaker.bronzeStock=12; GlassRibbonMaker.woodStock=12; GlassRibbonMaker.leatherStock=10; GlassRibbonMaker.silverStock=8; GlassRibbonMaker.goldStock=6; GlassRibbonMaker.jewelStock=4; GlassRibbonMaker.pearlStock=4; GlassRibbonMaker.productStock={}; GlassRibbonMaker.buildings={}; GlassRibbonMaker.maker=nil; GlassRibbonMaker.activeMaking={}; GlassRibbonMaker.totalProducts=0; GlassRibbonMaker.dayTimer=0; print("[GlassRibbonMaker] Royal Glass Ribbon Maker System initialized (6 products, 4 buildings)") end
function GlassRibbonMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassRibbonMaker.maker={name=n or ("Trakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trakar najet: %s (spretnost: %d)",GlassRibbonMaker.maker.name,s),"success") end; return true end
function GlassRibbonMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassRibbonMaker.build(id) local ok,e=GlassRibbonMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassRibbonMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassRibbonMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassRibbonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassRibbonMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassRibbonMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassRibbonMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassRibbonMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassRibbonMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassRibbonMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassRibbonMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassRibbonMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassRibbonMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassRibbonMaker.buildings==0 then return false,"Potrebna trakovna delavnica" end; if not GlassRibbonMaker.maker then return false,"Potreben trakar" end; return true end
function GlassRibbonMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassRibbonMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassRibbonMaker.ironStock=GlassRibbonMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassRibbonMaker.bronzeStock=GlassRibbonMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassRibbonMaker.woodStock=GlassRibbonMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassRibbonMaker.leatherStock=GlassRibbonMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassRibbonMaker.silverStock=GlassRibbonMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassRibbonMaker.goldStock=GlassRibbonMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassRibbonMaker.jewelStock=GlassRibbonMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassRibbonMaker.pearlStock=GlassRibbonMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassRibbonMaker.maker then t=math.max(1,t-math.floor(GlassRibbonMaker.maker.skill/13)) end; table.insert(GlassRibbonMaker.activeMaking,{id="glassribbon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassRibbonMaker.completeMaking(m) local q=1.0+(GlassRibbonMaker.getQualityBonus()/100); if GlassRibbonMaker.maker then q=q+(GlassRibbonMaker.maker.skill/140) end; q=math.min(2.5,q); GlassRibbonMaker.productStock[m.productType]=(GlassRibbonMaker.productStock[m.productType] or 0)+m.quantity; GlassRibbonMaker.totalProducts=GlassRibbonMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassRibbonMaker.maker then GlassRibbonMaker.maker.itemsMade=GlassRibbonMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassRibbonMaker.maker.skill=math.min(100,GlassRibbonMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trak izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassribbon.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassRibbonMaker.update(dt) if not _G.state then return end; GlassRibbonMaker.dayTimer=GlassRibbonMaker.dayTimer+dt; if GlassRibbonMaker.dayTimer>=30 then GlassRibbonMaker.dayTimer=0; for i=#GlassRibbonMaker.activeMaking,1,-1 do local m=GlassRibbonMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassRibbonMaker.completeMaking(m); table.remove(GlassRibbonMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassRibbonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassRibbonMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassRibbonMaker.getStats() return {ironStock=GlassRibbonMaker.ironStock,bronzeStock=GlassRibbonMaker.bronzeStock,woodStock=GlassRibbonMaker.woodStock,leatherStock=GlassRibbonMaker.leatherStock,silverStock=GlassRibbonMaker.silverStock,goldStock=GlassRibbonMaker.goldStock,jewelStock=GlassRibbonMaker.jewelStock,pearlStock=GlassRibbonMaker.pearlStock,productStock=GlassRibbonMaker.productStock,numBuildings=#GlassRibbonMaker.buildings,hasMaker=GlassRibbonMaker.maker~=nil,makerName=GlassRibbonMaker.maker and GlassRibbonMaker.maker.name or "—",makerSkill=GlassRibbonMaker.maker and GlassRibbonMaker.maker.skill or 0,activeMaking=#GlassRibbonMaker.activeMaking,totalProducts=GlassRibbonMaker.totalProducts} end
return GlassRibbonMaker
